@startuml

class Center {
  + Name
  + Address
}

class Room {
  + Number
  + MaxCapacity
}

class Person {
  + FirstName
  + FamilyName
  + BirthDate
}

class Trainer {
  + Diploma
}

abstract class Session {
  + Date
  + StartHour
}

class GroupSession extends Session {
  + Type
}

class IndividualSession extends Session {
}

Person "0..*" -- "0..*" Session : participates in

Trainer "0..1" -- "0..*" GroupSession : supervises

Center "1" *-- "1..*" Room
Center "1" -- "0..*" Session
Room "1" -- "0..*" Session

@enduml

